sys_script_include.script:
var FeedbackUtilsCS = Class.create();
FeedbackUtilsCS.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getFeedbackDetailsById: function() {
		var feedbackId = this.getParameter('sysparm_feedbackId');
        return JSON.stringify(new FeedbackUtilsScriptInclude().getFeedbackDetailsById(feedbackId));
    },

    isFeedbackPositive: function() {
		var feedbackId = this.getParameter('sysparm_feedbackId');
        return JSON.stringify(new FeedbackUtilsScriptInclude().isFeedbackPositive(feedbackId));
    },

    getFeedbackByEvent: function() {
		var eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new FeedbackUtilsScriptInclude().getFeedbackByEvent(eventId));
    },

    type: 'FeedbackUtilsCS'
});
